INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > MongoDB > Datenbanken (Details) > Begriffe
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind Collections in MongoDB vergleichbar mit Tabellen in relationalen Datenbanken?', 2, '[{"text": "Ja", "correct": true, "because": "Collections speichern Gruppen von Dokumenten ähnlich wie Tabellen"}, {"text": "Nein", "correct": false, "because": "Ähnliche Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Dokumente in MongoDB als einzelne Datensätze betrachtet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Dokumente sind eigenständige Dateneinheiten"}, {"text": "Nein", "correct": false, "because": "Definition von Dokumenten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der _id-Schlüssel in MongoDB immer eindeutig innerhalb einer Collection?', 2, '[{"text": "Ja", "correct": true, "because": "_id ist ein eindeutiger Identifikator"}, {"text": "Nein", "correct": false, "because": "Eindeutigkeit ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Collections in MongoDB Dokumente mit unterschiedlichen Strukturen enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Schemaflexibilität erlaubt verschiedene Strukturen"}, {"text": "Nein", "correct": false, "because": "Flexibilität ist Kernmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss jedes Dokument in MongoDB einen _id-Schlüssel enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "_id wird automatisch hinzugefügt, wenn nicht angegeben"}, {"text": "Nein", "correct": false, "because": "Pflichtfeld"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was entspricht in MongoDB am ehesten einer Tabelle in einer relationalen Datenbank?', 2, '[{"text": "Collection", "correct": true, "because": "Sammlung von Dokumenten"}, {"text": "Dokument", "correct": false, "because": "Einzelner Datensatz"}, {"text": "_id", "correct": false, "because": "Schlüssel, kein Container"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Begriff beschreibt einen einzelnen Datensatz in einer MongoDB-Collection?', 3, '[{"text": "Dokument", "correct": true, "because": "Ein Dokument ist ein Datensatz"}, {"text": "Collection", "correct": false, "because": "Gruppe von Dokumenten"}, {"text": "_id", "correct": false, "because": "Nur ein Schlüssel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feld dient in MongoDB als eindeutiger Identifikator für jedes Dokument?', 2, '[{"text": "_id", "correct": true, "because": "Automatisch eindeutig"}, {"text": "name", "correct": false, "because": "Nicht zwingend eindeutig"}, {"text": "index", "correct": false, "because": "Kein Standardfeld"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal von Collections in MongoDB unterscheidet sie von Tabellen?', 2, '[{"text": "Schemaflexibilität", "correct": true, "because": "Keine feste Struktur"}, {"text": "Feste Spaltenanzahl", "correct": false, "because": "Tabellenmerkmal"}, {"text": "Primärschlüssel", "correct": false, "because": "Relationale DB"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Dokument in MongoDB ohne _id-Feld eingefügt wird?', 2, '[{"text": "MongoDB fügt automatisch ein _id-Feld hinzu", "correct": true, "because": "Automatische Generierung"}, {"text": "Einfügen schlägt fehl", "correct": false, "because": "Nicht zwingend"}, {"text": "Dokument bleibt ohne _id", "correct": false, "because": "_id erforderlich"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Begriffe gehören zur Datenbankstruktur in MongoDB?', 4, '[{"text": "Collections", "correct": true, "because": "Gruppen von Dokumenten"}, {"text": "Dokumente", "correct": true, "because": "Einzelne Datensätze"}, {"text": "_id", "correct": true, "because": "Eindeutiger Schlüssel"}, {"text": "Tabellen", "correct": false, "because": "Relationale DB"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Dokumente in MongoDB?', 3, '[{"text": "JSON/BSON-Format", "correct": true, "because": "Standardformat"}, {"text": "Flexibles Schema", "correct": true, "because": "Keine feste Struktur"}, {"text": "Eindeutiges _id-Feld", "correct": true, "because": "Identifikator"}, {"text": "Feste Spaltenanzahl", "correct": false, "because": "Relationale DB"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale charakterisieren den _id-Schlüssel in MongoDB?', 4, '[{"text": "Eindeutigkeit", "correct": true, "because": "Innerhalb der Collection eindeutig"}, {"text": "Automatische Generierung", "correct": true, "because": "Falls nicht angegeben"}, {"text": "Pflichtfeld", "correct": true, "because": "Jedes Dokument benötigt es"}, {"text": "Nur numerisch", "correct": false, "because": "Kann auch String sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Collections in MongoDB?', 3, '[{"text": "Flexible Struktur", "correct": true, "because": "Unterschiedliche Dokumente"}, {"text": "Skalierbarkeit", "correct": true, "because": "Horizontal skalierbar"}, {"text": "Dynamische Anpassung", "correct": true, "because": "Keine Schemaänderung nötig"}, {"text": "Feste Datenintegrität", "correct": false, "because": "Relationale DB"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf die Dokumentenstruktur in MongoDB zu?', 3, '[{"text": "Kann eingebettete Dokumente enthalten", "correct": true, "because": "Hierarchische Daten"}, {"text": "Unterschiedliche Felder möglich", "correct": true, "because": "Schemaflexibilität"}, {"text": "Eindeutiges _id erforderlich", "correct": true, "because": "Identifikation"}, {"text": "Feste Spaltenanzahl", "correct": false, "because": "Nicht zutreffend"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Collections sind Gruppen von Dokumenten. b) Sie haben eine feste Struktur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gruppen ja, Struktur nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dokumente sind einzelne Datensätze in MongoDB. b) Sie müssen immer ein _id-Feld enthalten.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Datensätze ja, _id Pflicht"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) _id ist ein eindeutiger Schlüssel in MongoDB. b) Er kann doppelt in einer Collection vorkommen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eindeutig ja, doppelt nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Collections können unterschiedliche Dokumentstrukturen speichern. b) Dokumente sind auf tabellarische Daten beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, tabellarisch nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) _id wird automatisch generiert, wenn nicht angegeben. b) Collections entsprechen Spalten in relationalen DBs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Generierung ja, Spalten nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

